data class CallPalette(val background:Color,val text:Color,val accent:Color,val decline:Color,val subtitle:String)
fun palette(settings:AppSettings):CallPalette {
    fun parse(v:String,fallback:Color)=runCatching{Color(android.graphics.Color.parseColor(v))}.getOrDefault(fallback)
    return when(settings.callTheme){
        CallTheme.ANDROID->CallPalette(Color(0xFFF4F6F8),Color.Black,Color(0xFF34A853),Color(0xFFEA4335),"공연용 모의 Android 스타일")
        CallTheme.DARK->CallPalette(Color(0xFF07111F),Color.White,Color(0xFFD4AF37),Color(0xFFE53935),"MAGIC PERFORMANCE")
        CallTheme.SIMPLE->CallPalette(Color.Black,Color.White,Color.White,Color.DarkGray,"공연용 모의 전화")
        CallTheme.BLUE_FAN->CallPalette(Color(0xFF061B3A),Color.White,Color(0xFF77B5FF),Color(0xFFC7434D),"BLUE FAN · ORIGINAL PERFORMANCE")
        CallTheme.CUSTOM->CallPalette(parse(settings.customBackgroundColor,Color(0xFF07111F)),parse(settings.customTextColor,Color.White),parse(settings.customAccentColor,Color(0xFF3DDC84)),Color(0xFFE53935),"CUSTOM · 공연용 모의 전화")
    }
}

@Composable fun BlueFanCard(card:PlayingCard?,front:Boolean,modifier:Modifier=Modifier){val context=LocalContext.current;val reduce=runCatching{android.provider.Settings.Global.getFloat(context.contentResolver,android.provider.Settings.Global.ANIMATOR_DURATION_SCALE)==0f}.getOrDefault(false);val rotation by animateFloatAsState(if(front)180f else 0f,tween(if(reduce)0 else 700),label="card flip");Canvas(modifier.graphicsLayer{rotationY=rotation;cameraDistance=12*density}.semantics{contentDescription=if(front)"공개 카드 ${card?.shortCode.orEmpty()}" else "Blue Fan 카드 뒷면"}){val showFront=rotation>90;if(showFront){drawRoundRect(Color.White,cornerRadius=androidx.compose.ui.geometry.CornerRadius(28f));val c=card?:return@Canvas;drawContext.canvas.save();drawContext.canvas.scale(-1f,1f);drawCircle(if(c.suit in listOf(Suit.HEARTS,Suit.DIAMONDS)||c.jokerColor==JokerColor.RED)Color.Red else Color.Black,size.minDimension*.14f,center);drawContext.canvas.restore()}else{drawRoundRect(Color(0xFF0B4DA2),cornerRadius=androidx.compose.ui.geometry.CornerRadius(28f));drawRoundRect(Color.White,cornerRadius=androidx.compose.ui.geometry.CornerRadius(28f),style=Stroke(10f));for(i in 0 until 18){val a=i*Math.PI/9;drawLine(Color(0xFF8EC5FF),center,Offset(center.x+kotlin.math.cos(a).toFloat()*size.width*.42f,center.y+kotlin.math.sin(a).toFloat()*size.height*.42f),4f)};drawCircle(Color(0xFFDFEFFF),size.minDimension*.18f,center,style=Stroke(8f));drawCircle(Color(0xFF6FAEFF),size.minDimension*.08f,center)}}}

@Composable fun ThemedIncoming(vm:CardCallerViewModel,u:UiState){val card=u.selected?:return;val p=palette(u.settings);val context=LocalContext.current;DisposableEffect(Unit){val vibrator=if(Build.VERSION.SDK_INT>=31)(context.getSystemService(android.content.Context.VIBRATOR_MANAGER_SERVICE)as VibratorManager).defaultVibrator else @Suppress("DEPRECATION")(context.getSystemService(android.content.Context.VIBRATOR_SERVICE)as Vibrator);val ringtone=if(u.settings.ringtone)runCatching{RingtoneManager.getRingtone(context,RingtoneManager.getDefaultUri(RingtoneManager.TYPE_RINGTONE)).also{it.play()}}.getOrNull()else null;if(u.settings.vibrate)vibrator.vibrate(VibrationEffect.createWaveform(longArrayOf(0,450,400),0));onDispose{ringtone?.stop();vibrator.cancel()}};Column(Modifier.fillMaxSize().background(p.background).statusBarsPadding().padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally){Text(p.subtitle,color=p.accent,fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));BlueFanCard(card,false,Modifier.width(150.dp).aspectRatio(.7f));Spacer(Modifier.height(20.dp));Text(card.display(u.settings.displayFormat,CallerSettings.sanitizeName(u.settings.customCallerName)),fontSize=32.sp,color=p.text,fontWeight=FontWeight.Bold);Text(u.settings.customPhrase.ifBlank{"카드가 전화를 걸고 있습니다…"},color=p.text.copy(alpha=.7f));Spacer(Modifier.weight(1f));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceAround){Button(vm::reject,colors=ButtonDefaults.buttonColors(containerColor=p.decline)){Icon(Icons.Default.CallEnd,"공연 거절");Text(" 거절")};Button(vm::accept,colors=ButtonDefaults.buttonColors(containerColor=p.accent)){Icon(Icons.Default.Call,"공연 수신");Text(" 수신")}}}}

@Composable fun BlueFanReveal(vm:CardCallerViewModel,u:UiState){val c=u.selected?:return;var front by remember{mutableStateOf(false)};LaunchedEffect(Unit){front=true};Column(Modifier.fillMaxSize().statusBarsPadding().padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Text("MAGIC PERFORMANCE · 카드 공개",color=Color(0xFF77B5FF));BlueFanCard(c,front,Modifier.width(240.dp).aspectRatio(.7f));Text(c.display(CardDisplayFormat.KOREAN),fontSize=34.sp,fontWeight=FontWeight.Bold);Button(vm::openResult,Modifier.fillMaxWidth()){Text("공연 완료")};OutlinedButton({vm.navigate(Screen.PICKER)},Modifier.fillMaxWidth()){Text("다시 공연하기")};TextButton(vm::home){Text("홈으로 돌아가기")}}}

@Composable fun PerformanceResult(vm:CardCallerViewModel,u:UiState){val s=u.session;Column(Modifier.fillMaxSize().statusBarsPadding().padding(20.dp).verticalScroll(rememberScrollState())){Text("공연 결과",fontSize=30.sp,fontWeight=FontWeight.Bold);Text("카드: ${s?.card?.display(CardDisplayFormat.KOREAN)?:"-"}");Text("입력: ${s?.inputMethod?:"-"} · 트리거: ${s?.triggerMethod?:"-"}");Text("시작: ${s?.startedAt?.let{DateFormat.getDateTimeInstance().format(Date(it))}?:"-"}");Text("완료: ${s?.completedAt?.let{DateFormat.getDateTimeInstance().format(Date(it))}?:"완료 처리 전"}");Text("소요: ${performanceDuration(s?.startedAt?:0,s?.completedAt)?.div(1000)?:0}초");Text("관객 반응");listOf("👏 박수","😮 놀람","❤️ 좋아요","😐 보통").forEach{reaction->Button({vm.finishPerformance(reaction,true)},Modifier.fillMaxWidth().padding(3.dp)){Text(reaction)}};u.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};OutlinedButton(vm::home,Modifier.fillMaxWidth()){Text("홈으로 돌아가기")}}}

@Composable fun PerformanceSettingsV2(vm:CardCallerViewModel,u:UiState){var s by remember(u.settings){mutableStateOf(u.settings)};var delayText by remember{mutableStateOf(s.delaySeconds.toString())};Column(Modifier.fillMaxSize().statusBarsPadding().padding(16.dp).verticalScroll(rememberScrollState())){Text("공연 설정",fontSize=28.sp,fontWeight=FontWeight.Bold);Text("발신자 표시");Row(Modifier.horizontalScroll(rememberScrollState())){CardDisplayFormat.entries.forEach{FilterChip(s.displayFormat==it,{s=s.copy(displayFormat=it)},label={Text(it.name)},modifier=Modifier.padding(end=4.dp))}};OutlinedTextField(s.customCallerName,{s=s.copy(customCallerName=CallerSettings.sanitizeName(it))},label={Text("사용자 지정 발신자 이름 (최대 30자)")},supportingText={Text("${s.customCallerName.length}/30")},modifier=Modifier.fillMaxWidth());OutlinedTextField(s.customPhrase,{s=s.copy(customPhrase=it.take(60))},label={Text("사용자 지정 문구")},modifier=Modifier.fillMaxWidth());Text("지연 실행");Row(Modifier.horizontalScroll(rememberScrollState())){listOf(0,3,5,10).forEach{v->FilterChip(s.delaySeconds==v,{s=s.copy(delaySeconds=v);delayText=v.toString()},label={Text(if(v==0)"즉시"else"${v}초")},modifier=Modifier.padding(end=4.dp))}};OutlinedTextField(delayText,{value->delayText=value.filter(Char::isDigit).take(2);CallerSettings.delay(delayText)?.let{s=s.copy(delaySeconds=it)}},label={Text("사용자 지정 0~60초")},isError=CallerSettings.delay(delayText)==null,modifier=Modifier.fillMaxWidth());Text("수신 화면 테마");Row(Modifier.horizontalScroll(rememberScrollState())){CallTheme.entries.forEach{FilterChip(s.callTheme==it,{s=s.copy(callTheme=it)},label={Text(it.name)},modifier=Modifier.padding(end=4.dp))}};if(s.callTheme==CallTheme.CUSTOM){listOf("배경색" to s.customBackgroundColor,"강조색" to s.customAccentColor,"글자색" to s.customTextColor).forEach{(label,value)->OutlinedTextField(value,{v->s=when(label){"배경색"->s.copy(customBackgroundColor=v);"강조색"->s.copy(customAccentColor=v);else->s.copy(customTextColor=v)}},label={Text("$label #RRGGBB")},isError=ThemeSettings.validColor(value,"")!=value,modifier=Modifier.fillMaxWidth())}};Text("목표 정확도 ${s.targetAccuracy}%");Slider(s.targetAccuracy.toFloat(),{s=s.copy(targetAccuracy=it.toInt())},valueRange=1f..100f);Button({vm.saveSettings(s);vm.navigate(Screen.HOME)},Modifier.fillMaxWidth()){Text("설정 저장")}}}

@Composable fun FilteredPicker(vm:CardCallerViewModel,u:UiState,remote:Boolean){var suit by remember{mutableStateOf<Suit?>(null)};var rank by remember{mutableStateOf<Rank?>(null)};val cards=PlayingCard.deck.filter{(suit==null||it.suit==suit)&&(rank==null||it.rank==rank)};Column(Modifier.fillMaxSize().statusBarsPadding().padding(12.dp)){Text(if(remote)"원격 카드 선택"else"카드 직접 선택",fontSize=26.sp,fontWeight=FontWeight.Bold);Row(Modifier.horizontalScroll(rememberScrollState())){FilterChip(suit==null,{suit=null},label={Text("전체")});Suit.entries.forEach{x->FilterChip(suit==x,{suit=x},label={Text(x.symbol)},modifier=Modifier.padding(start=4.dp))}};Row(Modifier.horizontalScroll(rememberScrollState())){FilterChip(rank==null,{rank=null},label={Text("전체 값")});Rank.entries.forEach{x->FilterChip(rank==x,{rank=x},label={Text(x.label)},modifier=Modifier.padding(start=4.dp))}};LazyVerticalGrid(GridCells.Fixed(4),Modifier.weight(1f)){items(cards){c->Card(Modifier.padding(3.dp).aspectRatio(.7f).clickable{if(u.selected==c)vm.clearSelection()else vm.select(c)},colors=CardDefaults.cardColors(containerColor=Color.White)){Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){Text(if(u.settings.hideGestureResult&&u.settings.labMode==LabMode.PERFORMANCE)"◆" else c.shortCode,color=if(c.suit in listOf(Suit.HEARTS,Suit.DIAMONDS))Color.Red else Color.Black,fontWeight=FontWeight.Bold)}}}};u.selected?.let{Button({if(remote)vm.sendRemote(it)else vm.schedule()},Modifier.fillMaxWidth()){Text(if(remote)"카드 전송"else"전화 예약")}}}}

@Composable fun RehearsalDashboard(vm:CardCallerViewModel,u:UiState){val summary=RehearsalAnalytics.summarize(u.rehearsal);Column(Modifier.fillMaxSize().statusBarsPadding().padding(20.dp).verticalScroll(rememberScrollState())){Text("리허설 통계",fontSize=28.sp,fontWeight=FontWeight.Bold);Text("총 ${summary.total}회 · 성공 ${summary.successes}회");Text("정확도 ${"%.1f".format(summary.accuracy)}% · 평균 ${"%.2f".format(summary.averageMs/1000)}초");Text("가장 자주 틀린 카드: ${summary.mostMissedCard?:"없음"}");Text("목표 ${u.settings.targetAccuracy}% ${if(summary.accuracy>=u.settings.targetAccuracy)"달성 ✓"else"연습 중"}",color=if(summary.accuracy>=u.settings.targetAccuracy)Color(0xFF3DDC84) else Color.White);Text("무늬별: ${summary.bySuit}");Text("숫자별: ${summary.byRank}");Button({vm.navigate(Screen.GESTURE)},Modifier.fillMaxWidth()){Text("새 연습 시작")};OutlinedButton(vm::clearHistory,Modifier.fillMaxWidth()){Text("공연 기록 초기화")};Text("최근 공연 ${u.history.size}건");u.history.take(7).forEach{Text("${it.cardId} · ${it.status} · ${it.reaction?:"-"}")}}}
